Here's a sample C# code that implements a multi-level decision tree to classify different types of vehicles based on their specific features:
```
using System;
using System.Collections.Generic;
class Vehicle
{
    public int Wheels { get; set; }
    public int Horsepower { get; set; }
    public int Weight { get; set; }
    public string Classification { get; set; }
}
class Program
{
    static void Main(string[] args)
    {
        // Create a list of vehicles with their respective features
        List<Vehicle> vehicles = new List<Vehicle>
        {
            new Vehicle { Wheels = 4, Horsepower = 200, Weight = 3000 },
            new Vehicle { Wheels = 2, Horsepower = 50, Weight = 500 },
            new Vehicle { Wheels = 4, Horsepower = 300, Weight = 5000 },
            new Vehicle { Wheels = 2, Horsepower = 100, Weight = 250 },
            new Vehicle { Wheels = 4, Horsepower = 150, Weight = 2000 },
            new Vehicle { Wheels = 2, Horsepower = 150, Weight = 400 },
            new Vehicle { Wheels = 4, Horsepower = 500, Weight = 8000 },
            new Vehicle { Wheels = 4, Horsepower = 100, Weight = 1500 },
            new Vehicle { Wheels = 2, Horsepower = 250, Weight = 600 },
            new Vehicle { Wheels = 4, Horsepower = 50, Weight = 1000 }
        };
        // Classify each vehicle using a decision tree
        foreach (Vehicle vehicle in vehicles)
        {
            if (vehicle.Wheels == 2)
            {
                if (vehicle.Weight <= 500)
                {
                    vehicle.Classification = "Motorcycle";
                }
                else
                {
                    vehicle.Classification = "Car";
                }
            }
            else if (vehicle.Wheels == 4)
            {
                if (vehicle.Horsepower >= 300 && vehicle.Weight >= 5000)
                {
                    vehicle.Classification = "Truck";
                }
                else if (vehicle.Weight >= 2000)
                {
                    vehicle.Classification = "SUV";
                }
                else
                {
                    vehicle.Classification = "Car";
                }
            }
        }
        // Print the classification result for each vehicle
        foreach (Vehicle vehicle in vehicles)
        {
            Console.WriteLine("Wheels: {0}, Horsepower: {1}, Weight: {2}, Classification: {3}", vehicle.Wheels, vehicle.Horsepower, vehicle.Weight, vehicle.Classification);
        }
        Console.ReadLine();
    }
}
```
In this code, we first create a list of vehicles with their respective features. We then loop through each vehicle in the list and use a decision tree to classify it based on its features. The decision tree consists of a series of logical questions that lead to the correct classification of each vehicle. 
For example, if a vehicle has 2 wheels and a weight less than or equal to 500, it is classified as a motorcycle. If it has 2 wheels and a weight greater than 500, it is classified as a car. If it has 4 wheels, a horsepower greater than or equal to 300, and a weight greater than or equal to 5000, it is classified as a truck. If it has 4 wheels and a weight greater than or equal to 2000, it is classified as an SUV. Otherwise, it is classified as a car.
Finally, we print the classification result for each vehicle.

