    Json::Value root;
    Json::Reader reader;
    bool parsedSuccess = reader.parse(readBuffer, root, false);
    if (parsedSuccess) {
        const Json::Value actors = root["Actors"];
        std::cout << "The main actors in The Lord of the Rings are: " << actors.asString() << std::endl;
    }
