Certainly! Here's an example implementation of a binary search tree in Scala:
```scala
class Node(var value: Int, var left: Node = null, var right: Node = null)
class BinarySearchTree {
  private var root: Node = null
  def insert(value: Int): Unit = {
    root = insertNode(root, value)
  }
  private def insertNode(node: Node, value: Int): Node = {
    if (node == null) {
      return new Node(value)
    }
    if (value < node.value) {
      node.left = insertNode(node.left, value)
    } else if (value > node.value) {
      node.right = insertNode(node.right, value)
    }
    node
  }
  def search(value: Int): Boolean = {
    searchNode(root, value)
  }
  private def searchNode(node: Node, value: Int): Boolean = {
    if (node == null) {
      return false
    }
    if (node.value == value) {
      return true
    }
    if (value < node.value) {
      searchNode(node.left, value)
    } else {
      searchNode(node.right, value)
    }
  }
}
```
To insert a node into the tree, you simply call the `insert` method with the value you want to insert. To search for a node in the tree, you call the `search` method with the value you want to find. The `search` method returns `true` if the value is found in the tree, and `false` otherwise.
Here's an example usage of the binary search tree:
```scala
