    host: "localhost",
    user: "username",
    password: "password",
    database: "database_name"
)
do {
    try connection.open()
    print("Connected to database")
} catch(let error) {
    print("Error connecting to database: \(error)")
}
```
To insert the length and width values into the database, you can use the following code:
```Swift
let query = "INSERT INTO rectangle (length, width) VALUES (\(length), \(width))"
do {
    let result = try connection.execute(query)
    print("Inserted \(result.affectedRows) rows")
} catch(let error) {
    print("Error inserting values into database: \(error)")
}
```
To retrieve the length and width values from the database, you can use the following code:
```Swift
